-- '헤드리스 브라우저 SPA 채용 공고 스크래핑' 스터디 노트에 세 번째 후속 사례(사람인 relay/view
-- 공유 링크가 상세요강을 로드 후 별도 AJAX로 채워서 정적 fetch는 물론 헤드리스 렌더링으로도
-- 안정적으로 못 잡던 문제와, canonical URL로 정규화해 우회한 수정)를 이어붙이고, 같은 작업을
-- Self-Intro 프로젝트 경험의 experience_detail로도 남긴다. content_markdown 추가분은 이스케이프
-- 문제를 원천 차단하기 위해 16진 리터럴(X'...')로 기록한다 (V102~V112 컨벤션 준용).

UPDATE `study`
SET `content_markdown` = CONCAT(`content_markdown`, X''),
    `updated_at` = NOW()
WHERE `slug` = 'headless-browser-spa-job-posting-scraping';

INSERT INTO `experience_detail` (`experience_id`, `content`, `display_order`, `outcome`, `visible`)
SELECT `id`, '채용 공고 자동수집에서 사람인 relay 링크의 AJAX 지연 로딩 대응', 6,
       '헤드리스 렌더링을 붙여도 로그인월·AJAX 타이밍 문제가 남는 사람인 relay/view 공유 링크를, rec_idx만 뽑아 canonical 상세 URL(zf_user/jobs/view)로 정규화해 정적 fetch만으로 상세요강을 안정적으로 수집하도록 개선했습니다.',
       1
FROM `experience` WHERE `title` = '개인 풀스택 포트폴리오 플랫폼 구축 (Self-Intro)';
SET @detail_id = LAST_INSERT_ID();

INSERT INTO `experience_detail_skill` (`experience_detail_id`, `skill_id`, `list_order`)
SELECT @detail_id, `id`, ROW_NUMBER() OVER (ORDER BY `id`) - 1
FROM `skill` WHERE `name` IN ('Java', 'Spring Boot');

INSERT INTO `study_experience_detail` (`study_id`, `experience_detail_id`)
SELECT `id`, @detail_id FROM `study` WHERE `slug` = 'headless-browser-spa-job-posting-scraping';
